def lines_lr(A, n):  # down-right runs (r-c const)
    res={}
    for start in range(n):
        # diagonals: r-c = d, d from -(n-1)..n-1
        pass
    for d in range(-(n-1), n):
        cells=[(r,c) for r in range(n) for c in range(n) if r-c==d]
        runs=[]; cur=[]
        for (r,c) in cells:
            v=A[r,c]
            if v and cur and A[cur[-1]]==v and cur[-1][0]+1==r:
                cur.append((r,c))
            elif v:
                if cur: runs.append(cur)
                cur=[(r,c)]
            else:
                if cur: runs.append(cur); cur=[]
        if cur: runs.append(cur)
        for run in runs:
            res.setdefault(d,[]).append((A[run[0]], len(run), run[0], run[-1]))
    return res
